async function create(student) {

    const pool = getPool();

    const [result] = await pool.execute(
        `
        INSERT INTO students
        (
            user_id,
            roll_number,
            first_name,
            last_name,
            gender,
            phone,
            email,
            address,
            semester,
            section,
            department_id
        )
        VALUES (?,?,?,?,?,?,?,?,?,?,?)
        `,
        [
            student.user_id,
            student.roll_number,
            student.first_name,
            student.last_name,
            student.gender,
            student.phone,
            student.email,
            student.address,
            student.semester,
            student.section,
            student.department_id
        ]
    );

    return result.insertId;
}

async function update(id, student) {

    const pool = getPool();

    await pool.execute(
        `
        UPDATE students
        SET
            first_name=?,
            last_name=?,
            gender=?,
            phone=?,
            email=?,
            address=?,
            semester=?,
            section=?,
            department_id=?
        WHERE id=?
        `,
        [
            student.first_name,
            student.last_name,
            student.gender,
            student.phone,
            student.email,
            student.address,
            student.semester,
            student.section,
            student.department_id,
            id
        ]
    );
}

async function remove(id) {

    const pool = getPool();

    await pool.execute(
        "DELETE FROM students WHERE id=?",
        [id]
    );
}